import{_ as s,a0 as p,w as r,s as l,I as n,x as t,a1 as i,A as a,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"Linux有问必答：如何在Linux下禁用IPv6 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何在Linux下禁用IPv6 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何在Linux下禁用IPv6 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何在Linux下禁用IPv6 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150225 Linux FAQs with Answers--How to disable IPv6 on Linux","title":"Linux有问必答：如何在Linux下禁用IPv6","tag":"201505","desc":""},"relativePath":"201505/20150225 Linux FAQs with Answers--How to disable IPv6 on Linux.md","filePath":"[post].md"}'),u={name:"201505/20150225 Linux FAQs with Answers--How to disable IPv6 on Linux.md"};function v(P,e,c,h,I,x){const o=p("Link");return r(),l("div",null,[e[16]||(e[16]=n("h1",{id:"linux有问必答-如何在linux下禁用ipv6",tabindex:"-1"},[t("Linux有问必答：如何在Linux下禁用IPv6 "),n("a",{class:"header-anchor",href:"#linux有问必答-如何在linux下禁用ipv6","aria-label":"Permalink to “Linux有问必答：如何在Linux下禁用IPv6”"},"​")],-1)),e[17]||(e[17]=n("blockquote",null,[n("p",null,[n("strong",null,"问题"),t("：我发现我的一个应用程序在尝试通过IPv6建立连接，但是由于我们本地网络不允许分配IPv6的流量，IPv6连接会超时，应用程序的连接会回退到IPv4，这样就会造成不必要的延迟。由于我目前对IPv6没有任何需求，所以我想在我的Linux主机上禁用IPv6。有什么比较合适的方法呢？")])],-1)),e[18]||(e[18]=n("p",null,"IPv6被认为是IPv4——互联网上的传统32位地址空间——的替代产品，它用来解决现有IPv4地址空间即将耗尽的问题。然而，由于已经有大量主机、设备用IPv4连接到了互联网上，所以想在一夜之间将它们全部切换到IPv6几乎是不可能的。许多IPv4到IPv6的转换机制(例如：双协议栈、网络隧道、代理) 已经被提出来用来促进IPv6能被采用，并且很多应用也正在进行重写，如我们所提倡的，来增加对IPv6的支持。有一件事情可以确定，就是在可预见的未来里IPv4和IPv6势必将共存。",-1)),n("p",null,[e[1]||(e[1]=t("理想情况下，",-1)),i(o,{href:"http://www.google.com/intl/en/ipv6/statistics.html"},{default:a(()=>[...e[0]||(e[0]=[t("向IPv6过渡的进程",-1)])]),_:1}),e[2]||(e[2]=t("不应该被最终的用户所看见，但是IPv4/IPv6混合环境有时会让你碰到各种源于IPv4和IPv6之间不经意间的相互碰撞的问题。举个例子，你会碰到应用程序超时的问题，比如apt-get或ssh尝试通过IPv6连接失败、DNS服务器意外清空了IPv6的AAAA记录、或者你支持IPv6的设备不兼容你的互联网服务提供商遗留下的IPv4网络，等等等等。",-1))]),e[19]||(e[19]=d(`<p>当然这不意味着你应该盲目地在你的Linux机器上禁用IPv6。鉴于IPv6许诺的种种好处，作为社会的一份子我们最终还是要充分拥抱它的，但是作为给最终用户进行故障排除过程的一部分，如果IPv6确实是罪魁祸首，那你可以尝试去关闭它。</p><p>这里有一些让你在Linux中部分(例如：对于某个特定的网络接口)或全部禁用IPv6的小技巧。这些小贴士应该适用于所有主流的Linux发行版包括Ubuntu、Debian、Linux Mint、CentOS、Fedora、RHEL以及Arch Linux。</p><h3 id="查看ipv6在linux中是否被启用" tabindex="-1">查看IPv6在Linux中是否被启用 <a class="header-anchor" href="#查看ipv6在linux中是否被启用" aria-label="Permalink to “查看IPv6在Linux中是否被启用”">​</a></h3><p>所有现代Linux发行版默认都自动启用IPv6。为了能看到IPv6在你的Linux中是否被激活，可以使用ifconfig或ip命令。如果你在输入这些命令之后看到&quot;inet6&quot;字样的输出，那就意味着你的Linux系统启用了IPv6。</p><pre><code>$ ifconfig 
</code></pre><p><img src="https://farm8.staticflickr.com/7282/16415082398_5fb0920506_b.jpg" alt=""></p><pre><code>$ ip addr 
</code></pre><p><img src="https://farm8.staticflickr.com/7290/16415082248_c4e075548b_c.jpg" alt=""></p><h3 id="临时禁用ipv6" tabindex="-1">临时禁用IPv6 <a class="header-anchor" href="#临时禁用ipv6" aria-label="Permalink to “临时禁用IPv6”">​</a></h3><p>如果你想要在你的Linux系统上临时关闭IPv6，你可以用 /proc 文件系统。&quot;临时&quot;的意思是我们所做的禁用IPv6的更改在系统重启后将不被保存。IPv6会在你的Linux机器重启后再次被启用。</p><p>要将一个特定的网络接口禁用IPv6，使用以下命令：</p><pre><code>$ sudo sh -c &#39;echo 1 &gt; /proc/sys/net/ipv6/conf/&lt;interface-name&gt;/disable_ipv6&#39; 
</code></pre><p>举个例子，将eth0接口禁用IPv6：</p><pre><code>$ sudo sh -c &#39;echo 1 &gt; /proc/sys/net/ipv6/conf/eth0/disable_ipv6&#39; 
</code></pre><p><img src="https://farm8.staticflickr.com/7288/15982511863_0c1feafe7f_b.jpg" alt=""></p><p>重新启用eth0接口的IPv6：</p><pre><code>$ sudo sh -c &#39;echo 0 &gt; /proc/sys/net/ipv6/conf/eth0/disable_ipv6&#39; 
</code></pre><p>如果你想要将整个系统所有接口包括回环接口禁用IPv6，使用以下命令：</p><pre><code>$ sudo sh -c &#39;echo 1 &gt; /proc/sys/net/ipv6/conf/all/disable_ipv6&#39; 
</code></pre><h3 id="永久禁用ipv6" tabindex="-1">永久禁用IPv6 <a class="header-anchor" href="#永久禁用ipv6" aria-label="Permalink to “永久禁用IPv6”">​</a></h3><p>以上方法是不能永久禁用IPv6的，你一旦重启系统IPv6还是会被启用。如果你想要永久关闭它，有几个方法你可以试试。</p><h4 id="方法一" tabindex="-1">方法一 <a class="header-anchor" href="#方法一" aria-label="Permalink to “方法一”">​</a></h4><p>第一种方法是通过 /etc/sysctl.conf 文件对 /proc 进行永久修改。</p><p>换句话说，就是用文本编辑器打开 /etc/sysctl.conf 然后添加以下内容：</p><pre><code># 禁用整个系统所有接口的IPv6
net.ipv6.conf.all.disable_ipv6 = 1

# 禁用某一个指定接口的IPv6(例如：eth0, lo)
net.ipv6.conf.lo.disable_ipv6 = 1
net.ipv6.conf.eth0.disable_ipv6 = 1
</code></pre><p>在 /etc/sysctl.conf 使这些更改生效，运行以下命令：</p><pre><code>$ sudo sysctl -p /etc/sysctl.conf 
</code></pre><p>或者直接重启。</p><h4 id="方法二" tabindex="-1">方法二 <a class="header-anchor" href="#方法二" aria-label="Permalink to “方法二”">​</a></h4><p>另一个永久禁用IPv6的方法是在开机的时候传递一个必要的内核参数。</p><p>用文本编辑器打开 /etc/default/grub 并给GRUB_CMDLINE_LINUX变量添加&quot;ipv6.disable=1&quot;。</p><pre><code>$ sudo vi /etc/default/grub
</code></pre><hr><pre><code>GRUB_CMDLINE_LINUX=&quot;xxxxx ipv6.disable=1&quot;
</code></pre><p>上面的&quot;xxxxx&quot;代表任何已有的内核参数，在它后面添加&quot;ipv6.disable=1&quot;。</p><p><img src="https://farm8.staticflickr.com/7286/15982512103_ec5d940e58_b.jpg" alt=""></p><p>最后，不要忘记用以下方法保存对GRUB/GRUB2的修改：</p><p>Debian、Ubuntu或Linux Mint系统：</p><pre><code>$ sudo update-grub 
</code></pre><p>Fedora、CentOS/RHEL系统：</p><pre><code>$ sudo grub2-mkconfig -o /boot/grub2/grub.cfg 
</code></pre><p>现在只要你重启你的Linux系统，IPv6就会完全被禁用。</p><h3 id="禁用ipv6之后的其它可选步骤" tabindex="-1">禁用IPv6之后的其它可选步骤 <a class="header-anchor" href="#禁用ipv6之后的其它可选步骤" aria-label="Permalink to “禁用IPv6之后的其它可选步骤”">​</a></h3><p>这里有一些在你禁用IPv6后需要考虑的可选步骤，这是因为当你在内核里禁用IPv6后，其它程序也许仍然会尝试使用IPv6。在大多数情况下，应用程序的这种行为不太会影响到什么，但是出于效率或安全方面的原因，你可以为他们禁用IPv6。</p><h4 id="etc-hosts" tabindex="-1">/etc/hosts <a class="header-anchor" href="#etc-hosts" aria-label="Permalink to “/etc/hosts”">​</a></h4><p>根据你的设置， /etc/hosts 会包含一条或多条IPv6的hosts和它们的地址。用文本编辑器打开 /etc/hosts 并注释掉包含IPv6 hosts的脚本行。</p><pre><code>$ sudo vi /etc/hosts
</code></pre><hr><pre><code># comment these IPv6 hosts
# ::1     ip6-localhost ip6-loopback
# fe00::0 ip6-localnet
# ff00::0 ip6-mcastprefix
# ff02::1 ip6-allnodes
# ff02::2 ip6-allrouters
</code></pre><h4 id="network-manager" tabindex="-1">Network Manager <a class="header-anchor" href="#network-manager" aria-label="Permalink to “Network Manager”">​</a></h4><p>如果你在用NetworkManager来管理你的网络设置，你可以在NetworkManager里禁用IPv6。在NetworkManager打开wired connection，点击&quot;IPv6 Settings&quot;选项并在&quot;Method&quot;一栏选择&quot;Ignore&quot;，保存退出。</p><p><img src="https://farm8.staticflickr.com/7293/16394993017_21917f027b_o.png" alt=""></p><h4 id="ssh服务" tabindex="-1">SSH服务 <a class="header-anchor" href="#ssh服务" aria-label="Permalink to “SSH服务”">​</a></h4><p>默认情况下，OpenSSH服务(sshd)会去尝试捆绑IPv4和IPv6的地址。</p><p>要强制sshd只捆绑IPv4地址，用文本编辑器打开 /etc/ssh/sshd_config 并添加以下行。inet只适用于IPv4，而inet6是适用于IPv6的。</p><pre><code>$ sudo vi /etc/ssh/sshd_config
</code></pre><hr><pre><code>AddressFamily inet
</code></pre><p>然后重启sshd服务。</p><hr>`,60)),n("p",null,[e[4]||(e[4]=t("via: ",-1)),i(o,{href:"http://ask.xmodulo.com/disable-ipv6-linux.html"},{default:a(()=>[...e[3]||(e[3]=[t("http://ask.xmodulo.com/disable-ipv6-linux.html",-1)])]),_:1})]),n("p",null,[e[8]||(e[8]=t("作者：",-1)),i(o,{href:"http://ask.xmodulo.com/author/nanni"},{default:a(()=>[...e[5]||(e[5]=[t("Dan Nanni",-1)])]),_:1}),e[9]||(e[9]=t(" 译者：",-1)),i(o,{href:"https://github.com/ZTinoZ"},{default:a(()=>[...e[6]||(e[6]=[t("ZTinoZ",-1)])]),_:1}),e[10]||(e[10]=t(" 校对：",-1)),i(o,{href:"https://github.com/wxy"},{default:a(()=>[...e[7]||(e[7]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[13]||(e[13]=t("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[11]||(e[11]=[t("LCTT",-1)])]),_:1}),e[14]||(e[14]=t(" 原创翻译，",-1)),i(o,{href:"http://linux.cn/"},{default:a(()=>[...e[12]||(e[12]=[t("Linux中国",-1)])]),_:1}),e[15]||(e[15]=t(" 荣誉推出",-1))])])}const L=s(u,[["render",v]]);export{b as __pageData,L as default};
